WITH metrics AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY MONTH(shipped_date), carrier ORDER BY shipped_date, id) AS event_seq, AVG(cost) OVER (PARTITION BY order_id ORDER BY shipped_date, id ROWS BETWEEN 2 PRECEDING AND 1 PRECEDING) AS cost_avg_2_prior, ROUND(cost / SUM(cost) OVER (PARTITION BY status), 4) AS cost_share, SUM(cost) OVER (ORDER BY shipped_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_cost FROM shipments) SELECT s.id, s.order_id, s.carrier, s.shipped_date, s.delivered_date, s.cost, s.status, s.event_seq, s.cost_avg_2_prior, CASE WHEN carrier RLIKE '^(Flash|FedEx)$' THEN 'GROUP_A' WHEN carrier RLIKE '^(DHL|Kerry)$' THEN 'EXTENDED' ELSE 'PRIORITY' END AS carrier_zone, (SELECT AVG(t2.cost) FROM shipments t2 WHERE t2.order_id = s.order_id) AS avg_shipment_cost FROM metrics s ORDER BY id DESC NULLS LAST
